export type CommunityApi=ReturnType<typeof createHttpCommunityApi>;
export function bindCommunitySession(api:ApiClient,service:CommunityApi){const owner=api.session.get()?.sessionId;return new Proxy(service,{get(target,key,receiver){const value=Reflect.get(target,key,receiver);return typeof value==="function"?(...args:unknown[])=>{assertOwner(api,owner);return value(...args)}:value}});}
